        shl     bx, 1                       ; word elements
        mov     [motext__lineHead + bx], ax
; ---- lineLen[lineCount] = 0
        mov     ax, [motext__lineCount]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     word [motext__lineLen + bx], 0
