        call    motext__lineNew
        ret

; ============================================== sub textLoad ====

textLoad:
; ---- undoing = true
        mov     byte [motext__undoing], 1
; ---- if ( ch == '\n' ) {
        mov     al, [textLoad__ch]
        cmp     al, 10                      ; byte operands, no widening
        jne     .L283                       ; unsigned ==
; ---- lineNew()
        call    motext__lineNew
        jmp     .L284
