        mov     byte [motext__undoing], 0
        ret

; ============================================== sub show ====

show:
; ---- putNumber( n )
        mov     ax, [show__n]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
        ret

; ============================================== sub showLine ====

showLine:
; ---- n = lineSlice( ln, col, count, addr( buf ) )
        mov     ax, [showLine__ln]
        mov     [lineSlice__ln], ax
        mov     ax, [showLine__col]
        mov     [lineSlice__col], ax
        mov     ax, [showLine__count]
        mov     [lineSlice__count], ax
